import{_ as c,C as s,o as d,c as l,a6 as o,E as t,j as a,a as n}from"./chunks/framework.5dd0l9Wo.js";const b=JSON.parse('{"title":"Web Cache Poisoning","description":"Unkeyed inputs, cache-key confusion, parameter cloaking, fat GET, cache key injection, and internal caches.","frontmatter":{"title":"Web Cache Poisoning","description":"Unkeyed inputs, cache-key confusion, parameter cloaking, fat GET, cache key injection, and internal caches."},"headers":[],"relativePath":"cache-poisoning/index.md","filePath":"cache-poisoning/index.md"}'),h={name:"cache-poisoning/index.md"};function p(u,e,g,m,y,k){const i=s("LabGroup"),r=s("TopicComplete");return d(),l("div",null,[e[0]||(e[0]=o('<h1 id="web-cache-poisoning-·-the-tainted-blueprint" tabindex="-1">Web Cache Poisoning · The Tainted Blueprint <a class="header-anchor" href="#web-cache-poisoning-·-the-tainted-blueprint" aria-label="Permalink to &quot;Web Cache Poisoning · The Tainted Blueprint&quot;">​</a></h1><p class="wd-section-lede">Web caching speeds up the internet by storing a single master copy of a webpage and serving it to thousands of visitors. Web cache poisoning occurs when an attacker tricks the cache into saving an altered, malicious version of that page. The root cause is a fatal mismatch: an input changes what the webpage says, but the cache forgets to include that input in its filing system.</p><div class="wd-callout"><p><strong>💡 Everyday Analogy: The Community Notice Board.</strong> Imagine a library clerk who keeps master photocopies of bus timetables. The clerk indexes each paper strictly by destination city: <code>NYC</code>. One morning, a prankster hands the clerk a revised schedule with a handwritten sticky note on the back: <em>&quot;Reroute all buses to my private parking lot.&quot;</em> The photocopying machine accidentally prints the sticky note onto the schedule! The clerk files this tainted document under <code>NYC</code>. From that moment on, every commuter who asks for the NYC schedule receives the prankster&#39;s bogus instructions—without ever asking for them.</p></div><h2 id="case-file-2-the-anatomy-of-an-unkeyed-injection" tabindex="-1">Case File #2: The Anatomy of an Unkeyed Injection <a class="header-anchor" href="#case-file-2-the-anatomy-of-an-unkeyed-injection" aria-label="Permalink to &quot;Case File #2: The Anatomy of an Unkeyed Injection&quot;">​</a></h2><p>To deliver web pages in milliseconds, reverse proxies and Content Delivery Networks (CDNs) calculate a <strong>cache key</strong>—a fingerprint of the request—typically made from the HTTP method, the host header, and the URL path.</p><div class="wd-case"><div class="wd-step wd-step--see"><span class="wd-step__tag">🔎 Step 1 · What You Notice in the Browser</span><p>An ordinary user browses to the website homepage (<code>https://example.com/</code>). Without warning, their browser downloads and runs a third-party tracking script hosted on an attacker-owned domain, silently intercepting keystrokes or cookies.</p></div><div class="wd-step wd-step--server"><span class="wd-step__tag">⚙️ Step 2 · What the Server Does Behind the Scenes</span><p>The CDN edge receives a request for <code>/en</code>. It checks its local cache table for the key <code>GET /en</code>. Finding no stored copy (a cache miss), it passes the request to the origin backend application.</p></div><div class="wd-step wd-step--break"><span class="wd-step__tag">💥 Step 3 · Where the Logic Breaks</span><p>The origin reads an optional header, <code>X-Forwarded-Host: attacker.com</code>, and uses it to construct a dynamic script link: <code>&lt;script src=&quot;https://attacker.com/analytics.js&quot;&gt;</code>. Crucially, the CDN never included <code>X-Forwarded-Host</code> in its cache key formula! It stores this corrupted HTML under the generic key <code>GET /en</code>.</p></div><div class="wd-step wd-step--fix"><span class="wd-step__tag">🛡️ Step 4 · How Developers Lock It Down</span><p>Add all headers that alter HTML output into the cache key using the <code>Vary</code> header (e.g., <code>Vary: X-Forwarded-Host</code>), or configure the CDN to strip unrecognized headers before the origin ever sees them.</p></div></div><h3 id="visual-comparison-keyed-identity-vs-unkeyed-content" tabindex="-1">Visual Comparison: Keyed Identity vs. Unkeyed Content <a class="header-anchor" href="#visual-comparison-keyed-identity-vs-unkeyed-content" aria-label="Permalink to &quot;Visual Comparison: Keyed Identity vs. Unkeyed Content&quot;">​</a></h3><div class="wd-compare"><div class="wd-compare__card wd-compare__card--expect"><span class="wd-compare__title">💭 What the Developer Expected</span><p>The cache key uniquely identifies safe, identical content. Any header not listed in the cache key is purely internal metadata that will never change the visual output of the page for other people.</p></div><div class="wd-compare__card wd-compare__card--actual"><span class="wd-compare__title">💥 What Actually Happened</span><p>An unkeyed header altered the dynamic HTML response. The cache faithfully saved the altered response under the public cache key, distributing the malicious script to thousands of subsequent clean visitors.</p></div></div><h3 id="watching-the-cache-key-miss-the-trap" tabindex="-1">Watching the Cache Key Miss the Trap <a class="header-anchor" href="#watching-the-cache-key-miss-the-trap" aria-label="Permalink to &quot;Watching the Cache Key Miss the Trap&quot;">​</a></h3><p>Look at how the CDN generates its filing index while ignoring the attacker&#39;s payload:</p><div class="wd-codesplit"><div class="wd-codesplit__legend"><span><span class="wd-code-dev">Blue</span> = Included in Cache Key (Method + Host + Path)</span><span><span class="wd-code-input">Gold</span> = Ignored by Cache Key (Unkeyed Poison Header)</span></div><span class="wd-code-dev">GET /en?cb=1 HTTP/1.1<br>Host: example.com<br></span><span class="wd-code-input">X-Forwarded-Host: attacker.com<br></span><span class="wd-code-dev">User-Agent: Mozilla/5.0...</span></div><details class="details custom-block"><summary>🔬 Under the Hood: The Four-Phase Detective Routine for Cache Poisoning</summary><p>How do security engineers safely uncover unkeyed inputs without impacting live users?</p><ol><li><strong>Find a Cacheable Static/Public Endpoint:</strong> Look for pages returning <code>X-Cache: hit</code> or <code>CF-Cache-Status: HIT</code> with reasonable <code>max-age</code> durations.</li><li><strong>Inject a Cache Buster:</strong> Append a randomized query string (<code>?cb=12345</code>) so your probe creates its own isolated cache slot and doesn&#39;t pollute real visitors.</li><li><strong>Probe Candidate Headers:</strong> Transmit canary headers (<code>X-Forwarded-Host</code>, <code>X-Forwarded-Scheme</code>, <code>X-Original-URL</code>, <code>X-Host</code>, <code>Forwarded</code>).</li><li><strong>Inspect Response Reflection:</strong> Check whether the canary string appears in HTML tags, redirects, or JavaScript objects. If it does, and the page is stored as a cache hit, the endpoint is vulnerable to poisoning.</li></ol></details><hr><h2 id="the-5-stage-life-of-a-cache-poisoning-attack" tabindex="-1">The 5-Stage Life of a Cache Poisoning Attack <a class="header-anchor" href="#the-5-stage-life-of-a-cache-poisoning-attack" aria-label="Permalink to &quot;The 5-Stage Life of a Cache Poisoning Attack&quot;">​</a></h2><p>Follow the lifecycle of an unkeyed request from initial probe to victim infection:</p><div class="wd-flow"><div class="wd-flow__node wd-flow__node--danger"><strong>1. Attacker Primer</strong> Attacker sends a request containing the unkeyed header (e.g. <code>X-Forwarded-Host</code>). </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node"><strong>2. Edge Cache Miss</strong> The cache has no saved entry for this path; it forwards the request upstream to origin. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--danger"><strong>3. Origin Taint</strong> Origin dynamically renders the attacker&#39;s host into a script tag or stylesheet link. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node"><strong>4. Cache Storage</strong> Edge cache saves the tainted HTML under the clean public cache key. </div><span class="wd-flow__arrow">→</span><div class="wd-flow__node wd-flow__node--safe"><strong>5. Victim Compromise</strong> Every subsequent visitor requests the clean URL and receives the poisoned cached file! </div></div><hr><h2 id="cache-keys-and-unkeyed-inputs" tabindex="-1">Cache Keys and Unkeyed Inputs <a class="header-anchor" href="#cache-keys-and-unkeyed-inputs" aria-label="Permalink to &quot;Cache Keys and Unkeyed Inputs&quot;">​</a></h2><p>The core vulnerability always boils down to an input that changes the response without being part of the cache key. This can occur via unexpected headers, unkeyed tracking cookies, or multiple conflicting headers working in tandem.</p>',19)),t(i,{ids:"cache-poisoning-lab-web-cache-poisoning-with-an-unkeyed-header, cache-poisoning-lab-web-cache-poisoning-with-an-unkeyed-cookie, cache-poisoning-lab-web-cache-poisoning-with-multiple-headers"}),e[1]||(e[1]=a("hr",null,null,-1)),e[2]||(e[2]=a("h2",{id:"targeted-poisoning-and-unknown-headers",tabindex:"-1"},[n("Targeted Poisoning and Unknown Headers "),a("a",{class:"header-anchor",href:"#targeted-poisoning-and-unknown-headers","aria-label":'Permalink to "Targeted Poisoning and Unknown Headers"'},"​")],-1)),e[3]||(e[3]=a("p",null,"Some unkeyed inputs only trigger when paired with specific conditions or user-agent categories. A targeted attack may poison responses served specifically to mobile browsers, desktop clients, or administrative paths by combining unkeyed behavior with targeted cache variations.",-1)),t(i,{ids:"cache-poisoning-lab-web-cache-poisoning-targeted-using-an-unknown-header"}),e[4]||(e[4]=o('<hr><h2 id="query-parameters-and-parameter-cloaking" tabindex="-1">Query Parameters and Parameter Cloaking <a class="header-anchor" href="#query-parameters-and-parameter-cloaking" aria-label="Permalink to &quot;Query Parameters and Parameter Cloaking&quot;">​</a></h2><p>Not all unkeyed inputs live in headers. Caches are frequently configured to strip marketing tags (such as <code>utm_content</code> or <code>utm_campaign</code>) from their cache keys to maximize hit ratios.</p><ul><li><strong>Unkeyed Query Strings:</strong> The cache strips the entire query string from the key, allowing any reflected parameter to poison the page for everyone.</li><li><strong>Unkeyed Single Parameters:</strong> A specific parameter is stripped from the key but evaluated by the backend application logic.</li><li><strong>Parameter Cloaking:</strong> Using parsing quirks like semicolons (<code>;</code>) or ampersands (<code>&amp;</code>) to make the cache think there is only one parameter while the backend framework parses two distinct parameters.</li><li><strong>Fat GET Requests:</strong> Sending an HTTP body inside a <code>GET</code> request. The cache generates its key solely from the URL, but the origin framework extracts data from the body!</li></ul>',4)),t(i,{ids:"cache-poisoning-lab-web-cache-poisoning-unkeyed-query, cache-poisoning-lab-web-cache-poisoning-unkeyed-param, cache-poisoning-lab-web-cache-poisoning-param-cloaking, cache-poisoning-lab-web-cache-poisoning-fat-get"}),e[5]||(e[5]=a("hr",null,null,-1)),e[6]||(e[6]=a("h2",{id:"normalization-and-cache-key-injection",tabindex:"-1"},[n("Normalization and Cache Key Injection "),a("a",{class:"header-anchor",href:"#normalization-and-cache-key-injection","aria-label":'Permalink to "Normalization and Cache Key Injection"'},"​")],-1)),e[7]||(e[7]=a("p",null,"When the cache and the origin server parse URI paths differently, an attacker can trick the cache into serving the wrong resource.",-1)),e[8]||(e[8]=a("ul",null,[a("li",null,[a("strong",null,"Normalization Discrepancies:"),n(" The cache normalizes percent-encoded characters or dot segments ("),a("code",null,"/test/../home"),n("), while the backend reads raw strings—or vice versa.")]),a("li",null,[a("strong",null,"Cache Key Injection:"),n(" Caches that construct keys by concatenating headers with delimiter characters can be tricked when an attacker injects the delimiter into an input, overwriting another user's cache entry.")])],-1)),t(i,{ids:"cache-poisoning-lab-web-cache-poisoning-normalization, cache-poisoning-lab-web-cache-poisoning-cache-key-injection"}),e[9]||(e[9]=a("hr",null,null,-1)),e[10]||(e[10]=a("h2",{id:"chaining-and-dom-sinks",tabindex:"-1"},[n("Chaining and DOM Sinks "),a("a",{class:"header-anchor",href:"#chaining-and-dom-sinks","aria-label":'Permalink to "Chaining and DOM Sinks"'},"​")],-1)),e[11]||(e[11]=a("p",null,[n("Cache poisoning becomes devastating when combined with client-side DOM vulnerabilities. Even when an application enforces strict cacheability criteria (such as only caching responses with specific file extensions or MIME types), crafted paths can satisfy the cache rules while reflecting untrusted values into DOM sinks like "),a("code",null,"innerHTML"),n(" or "),a("code",null,"eval()"),n(".")],-1)),t(i,{ids:"cache-poisoning-lab-web-cache-poisoning-to-exploit-a-dom-vulnerability-via-a-cache-with-strict-cacheability-criteria, cache-poisoning-lab-web-cache-poisoning-combining-vulnerabilities"}),e[12]||(e[12]=a("hr",null,null,-1)),e[13]||(e[13]=a("h2",{id:"internal-caches-and-fragment-caches",tabindex:"-1"},[n("Internal Caches and Fragment Caches "),a("a",{class:"header-anchor",href:"#internal-caches-and-fragment-caches","aria-label":'Permalink to "Internal Caches and Fragment Caches"'},"​")],-1)),e[14]||(e[14]=a("p",null,"Caches do not only exist at large commercial CDNs like Cloudflare or Akamai. Many application architectures use internal caching layers:",-1)),e[15]||(e[15]=a("ul",null,[a("li",null,"Local Varnish reverse proxies"),a("li",null,[n("Nginx "),a("code",null,"proxy_cache"),n(" zones")]),a("li",null,"Framework-level fragment caches (such as Symfony or Ruby on Rails action caching)")],-1)),e[16]||(e[16]=a("p",null,"Because internal caches operate behind edge firewalls, they often accept internal forward headers that would normally be blocked at the outer perimeter.",-1)),t(i,{ids:"cache-poisoning-lab-web-cache-poisoning-internal"}),e[17]||(e[17]=o('<details class="details custom-block"><summary>⚙️ Engine Variations: How Major Cache Servers Handle Keys</summary><ul><li><strong>Varnish Cache:</strong> The <code>vcl_hash</code> subroutine builds the cache key. If developers strip or modify headers inside <code>vcl_recv</code> before hashing, unkeyed behaviors quickly arise.</li><li><strong>Nginx <code>proxy_cache_key</code>:</strong> By default set to <code>$scheme$proxy_host$request_uri</code>. Query parameters are included by default, but headers are omitted unless explicitly defined.</li><li><strong>Cloudflare:</strong> Includes scheme, host, and path by default. Query strings are included, but &quot;Cache Everything&quot; page rules can accidentally expose personalized endpoints.</li><li><strong>Akamai:</strong> Relies on Property Manager rules where cache key inclusions/exclusions are defined per behavioral path match.</li><li><strong>Fastly:</strong> Built on custom VCL; provides full programmable control over hash keys and header normalization.</li></ul><p>Cache poisoning is rarely a bug in the cache software itself; it is almost always a mismatch in how the edge proxy and backend origin interpret the request.</p></details><div class="wd-callout wd-callout--warn"><p><strong>🛡️ Defensive Blueprint: How to Lock Down Caches</strong></p><ol><li><strong>Never Reflect Unkeyed Inputs:</strong> If a header or parameter changes the HTML response, it MUST be included in the cache key or declared via the <code>Vary</code> header.</li><li><strong>Strip Unnecessary Headers at the Edge:</strong> Configure the edge reverse proxy to strip <code>X-Forwarded-*</code> and internal routing headers before requests reach backend code.</li><li><strong>Explicit Private Directives:</strong> Mark dynamic or personalized pages with <code>Cache-Control: private, no-store, max-age=0</code>.</li><li><strong>Harmonize Normalization:</strong> Ensure the cache and origin use identical path-parsing and parameter-parsing rules.</li></ol></div>',2)),t(r,{"topic-id":"web-cache-poisoning",label:"Mark cache poisoning complete"})])}const f=c(h,[["render",p]]);export{b as __pageData,f as default};
